mod meter;mod pic;
#[path="../native-smith-transport/pic.rs"]mod legacy_pic;
#[path="../native-smith-transport/models.rs"]mod models;
#[path="../native-smith-transport/transport.rs"]mod transport;
mod legacy_transport;
#[path="../native-smith-secants/ic.rs"]mod ic;
mod legacy_ic;
#[path="../native-smith-quartic-ic/ic.rs"]mod exhaustive;
use hec_native_ic::{counted,instance::pick_instance,rng::Rng,jac::{Curve,Div}};
struct Fixture{case:usize,multiple:u64,d:Div,t:Div,label:u64}
struct Snapshot{native:counted::Counts,pic:meter::Counts}
impl Snapshot{fn now()->Self{Self{native:counted::snapshot(),pic:meter::snapshot()}}}
#[derive(Debug)]struct Phase{name:String,native:counted::Counts,legacy:[u64;3],full:meter::Counts}
fn native_delta(before:&counted::Counts)->counted::Counts{let mut out=counted::snapshot();for(q,v)in out.iter_mut(){let b=before.get(q).copied().unwrap_or([0;16]);for i in 0..16{v[i]-=b[i];}}out.retain(|_,v|v.iter().any(|&x|x!=0));out}
fn finish(name:&str,map:usize,arm:&str,b:Snapshot,legacy:[u64;3],instrumented:bool)->Phase{let phase=Phase{name:name.to_string(),native:native_delta(&b.native),legacy,full:meter::delta(&b.pic)};if instrumented{let v=phase.full.get(&61).copied().unwrap_or([0;11]);assert!(v[0]+v[1]+v[2]>=legacy[0]);assert!(v[3]+v[4]>=legacy[1]);}else{assert!(phase.full.is_empty());}println!("PHASE map={map} arm={arm} name={name} legacy_pic={legacy:?} full_pic={:?} native={:?}",phase.full,phase.native);phase}
#[derive(Debug,PartialEq,Eq)]struct Signature{p0:[u64;3],details:Vec<String>,native:Vec<counted::Counts>,legacy:Vec<[u64;3]>}
struct Outcome{signature:Signature,phases:Vec<Phase>}
fn run_legacy(source:&Curve,aux:&Div,model:&models::Model,fixtures:&[Fixture],ell:u64,map:usize)->Outcome{use crate::legacy_pic as p;use crate::legacy_ic as collector;use crate::legacy_transport as mapper;const ARM:&str="legacy";const INSTRUMENTED:bool=false;
let mut phases=Vec::new();let mut details=Vec::new();let b=Snapshot::now();let p0=p::first_rational_point_canonical(61,&model.coeff).unwrap();phases.push(finish("point_search",map,ARM,b,[0;3],INSTRUMENTED));let b=Snapshot::now();let pc=p::PlaneQuartic::new(61,model.coeff,p0).unwrap();let counter=pc.counter();phases.push(finish("constructor",map,ARM,b,[counter.mul,counter.inv,counter.add],INSTRUMENTED));let b=Snapshot::now();let before=pc.counter();let base=collector::build(&pc,ell,map);let d=pc.counter().since(&before);phases.push(finish("secant_setup",map,ARM,b,[d.mul,d.inv,d.add],INSTRUMENTED));details.push(format!("base:{}:{}:{}:{:?}",base.pair_trials,base.rank,base.split_lines,base.certificates));for fix in fixtures{let b=Snapshot::now();let before=pc.counter();let g=mapper::transport(source,&fix.d,aux,model,&pc,1).unwrap();let t=mapper::transport(source,&fix.t,aux,model,&pc,1).unwrap();let delta=pc.counter().since(&before);phases.push(finish(&format!("transport{}",fix.case),map,ARM,b,[delta.mul,delta.inv,delta.add],INSTRUMENTED));details.push(format!("keys:{}:{:?}:{:?}:{}:{}:{}:{}",fix.case,g.class.key().0,t.class.key().0,g.aux_scalar,g.rejected,t.aux_scalar,t.rejected));let b=Snapshot::now();let before=pc.counter();let report=collector::solve(&pc,&g.class,&t.class,ell,&base,2026112400^(map as u64)^((fix.case as u64)<<32)).unwrap();let delta=pc.counter().since(&before);phases.push(finish(&format!("quartic_ic{}",fix.case),map,ARM,b,[delta.mul,delta.inv,delta.add],INSTRUMENTED));assert_eq!(report.k,fix.label);assert_eq!(report.trials,[[7,35],[16,17]][map][fix.case]);assert_eq!(report.smooth,2);details.push(format!("report{}:{report:?}",fix.case));let b=Snapshot::now();assert_eq!(source.mul(&fix.d,report.k),fix.t);phases.push(finish(&format!("original_verify{}",fix.case),map,ARM,b,[0;3],INSTRUMENTED));println!("SOLVE map={map} arm={ARM} case={} multiple={} k={} original_h_verified=true",fix.case,fix.multiple,report.k);}details.push(format!("stats:{:?}",pc.stats()));let signature=Signature{p0,details,native:phases.iter().map(|p|p.native.clone()).collect(),legacy:phases.iter().map(|p|p.legacy).collect()};Outcome{signature,phases}
}
fn run_metered(source:&Curve,aux:&Div,model:&models::Model,fixtures:&[Fixture],ell:u64,map:usize)->Outcome{use crate::pic as p;use crate::ic as collector;use crate::transport as mapper;const ARM:&str="metered";const INSTRUMENTED:bool=true;
let mut phases=Vec::new();let mut details=Vec::new();let b=Snapshot::now();let p0=p::first_rational_point_canonical(61,&model.coeff).unwrap();phases.push(finish("point_search",map,ARM,b,[0;3],INSTRUMENTED));let b=Snapshot::now();let pc=p::PlaneQuartic::new(61,model.coeff,p0).unwrap();let counter=pc.counter();phases.push(finish("constructor",map,ARM,b,[counter.mul,counter.inv,counter.add],INSTRUMENTED));let b=Snapshot::now();let before=pc.counter();let base=collector::build(&pc,ell,map);let d=pc.counter().since(&before);phases.push(finish("secant_setup",map,ARM,b,[d.mul,d.inv,d.add],INSTRUMENTED));details.push(format!("base:{}:{}:{}:{:?}",base.pair_trials,base.rank,base.split_lines,base.certificates));for fix in fixtures{let b=Snapshot::now();let before=pc.counter();let g=mapper::transport(source,&fix.d,aux,model,&pc,1).unwrap();let t=mapper::transport(source,&fix.t,aux,model,&pc,1).unwrap();let delta=pc.counter().since(&before);phases.push(finish(&format!("transport{}",fix.case),map,ARM,b,[delta.mul,delta.inv,delta.add],INSTRUMENTED));details.push(format!("keys:{}:{:?}:{:?}:{}:{}:{}:{}",fix.case,g.class.key().0,t.class.key().0,g.aux_scalar,g.rejected,t.aux_scalar,t.rejected));let b=Snapshot::now();let before=pc.counter();let report=collector::solve(&pc,&g.class,&t.class,ell,&base,2026112400^(map as u64)^((fix.case as u64)<<32)).unwrap();let delta=pc.counter().since(&before);phases.push(finish(&format!("quartic_ic{}",fix.case),map,ARM,b,[delta.mul,delta.inv,delta.add],INSTRUMENTED));assert_eq!(report.k,fix.label);assert_eq!(report.trials,[[7,35],[16,17]][map][fix.case]);assert_eq!(report.smooth,2);details.push(format!("report{}:{report:?}",fix.case));let b=Snapshot::now();assert_eq!(source.mul(&fix.d,report.k),fix.t);phases.push(finish(&format!("original_verify{}",fix.case),map,ARM,b,[0;3],INSTRUMENTED));println!("SOLVE map={map} arm={ARM} case={} multiple={} k={} original_h_verified=true",fix.case,fix.multiple,report.k);}details.push(format!("stats:{:?}",pc.stats()));let signature=Signature{p0,details,native:phases.iter().map(|p|p.native.clone()).collect(),legacy:phases.iter().map(|p|p.legacy).collect()};Outcome{signature,phases}
}
fn run_reference(model:&models::Model,p0:pic::Pt,ell:u64,map:usize){let b=Snapshot::now();let pc=pic::PlaneQuartic::new(61,model.coeff,p0).unwrap();let c=pc.counter();finish("reference_constructor",map,"metered",b,[c.mul,c.inv,c.add],true);let b=Snapshot::now();let c=pc.counter();let base=exhaustive::build(&pc,ell,map);let d=pc.counter().since(&c);let record=finish("exhaustive_setup",map,"metered",b,[d.mul,d.inv,d.add],true);assert_eq!(base.split_lines,209);println!("REFERENCE map={map} full_pic={:?} native={:?}",record.full,record.native);}
fn main(){counted::reset();pic::meter_selfcheck();let inst=pick_instance(61,3).unwrap();assert_eq!(inst.ell,124459);let mut rng=Rng::new(2026111800^61^(3<<32));let fixtures=(0..2).map(|case|{let multiple=if case==0{1}else{17};let d=inst.curve.mul(&inst.d1,multiple);let label=1+rng.below(inst.ell-1);let t=inst.curve.mul(&d,label);Fixture{case,multiple,d,t,label}}).collect::<Vec<_>>();for(map,model)in models::models().iter().enumerate(){let (legacy,new)=if map%2==0{let legacy=run_legacy(&inst.curve,&inst.d1,model,&fixtures,inst.ell,map);let new=run_metered(&inst.curve,&inst.d1,model,&fixtures,inst.ell,map);(legacy,new)}else{let new=run_metered(&inst.curve,&inst.d1,model,&fixtures,inst.ell,map);let legacy=run_legacy(&inst.curve,&inst.d1,model,&fixtures,inst.ell,map);(legacy,new)};assert_eq!(legacy.signature,new.signature,"instrumentation altered numerical flow, legacy counters or native vectors");let setup=new.phases.iter().find(|p|p.name=="secant_setup").unwrap();let v=setup.full.get(&61).unwrap();assert!(v[0]+v[1]+v[2]>0);println!("CALIBRATION map={map} exact_keys_aux_relations_reports_legacy_counts_native_vectors=true phase_count={} corrected_setup_pic_mul={} corrected_setup_pic_inv={}",new.phases.len(),v[0]+v[1]+v[2],v[3]+v[4]);run_reference(model,new.signature.p0,inst.ell,map);}counted::disable();eprintln!("PASS primitive_endpoint_meter=true paired_numerical_replay=true original_solves=8 pic_product_inverse_coverage_repaired=true no_complete_attack_cost_or_speed_claim=true");}
